    public static void main(String[] args) {
        GrowList names = new GrowList();
        names.add("An");
        names.add("Mai");
        names.add("Tuan");
        names.add("Linh");
        names.add("Binh");
        System.out.println(names.size() + " of " + names.capacity());
        System.out.println(names.get(4));
    }
}

class GrowList {
    private String[] items = new String[4];
    private int size = 0;

    void add(String value) {
        if (size == items.length) {
            String[] bigger = new String[items.length + items.length / 2];
            for (int i = 0; i < size; i++) {
                bigger[i] = items[i];
            }
            items = bigger;
        }
        items[size] = value;
        size++;
    }

    String get(int index) {
        if (index >= size) {
            throw new IndexOutOfBoundsException("index " + index + ", size " + size);
        }
        return items[index];
    }

    int size() { return size; }
    int capacity() { return items.length; }
}

