    public static void main(String[] args) {
        LinkedQueue queue = new LinkedQueue();
        queue.enqueue("An");
        queue.enqueue("Mai");
        queue.enqueue("Tuan");
        System.out.println(queue.dequeue());
        System.out.println(queue.dequeue());
        queue.enqueue("Linh");
