        System.out.println(queue.dequeue());
        System.out.println(queue.isEmpty());
    }
}

class Node {
    String value;
    Node next;

    Node(String value) {
        this.value = value;
    }
}

class LinkedQueue {
    private Node head;
    private Node tail;

    void enqueue(String value) {
        Node node = new Node(value);
        if (tail == null) {
            head = node;
        } else {
            tail.next = node;
        }
        tail = node;
    }

    String dequeue() {
        String value = head.value;
        head = head.next;
        if (head == null) {
            tail = null;
        }
        return value;
    }

    boolean isEmpty() {
        return head == null;
    }
}

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


class LinkedQueue:
    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, value):
        node = Node(value)
        if self.tail is None:
            self.head = node
        else:
            self.tail.next = node
        self.tail = node

    def dequeue(self):
        value = self.head.value
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        return value

    def is_empty(self):
        return self.head is None


